m News of the World contained \"We Will Rock You\" and \"We Are the Champions\", which have become anthems at sporting events.\n\nFrom Wikipedia ("},{"text":"https://en.wikipedia.org/wiki/Queen_(...","navigationEndpoint":{"urlEndpoint":{"url":"https://en.wikipedia.org/wiki/Queen_(band)","target":"TARGET_NEW_WINDOW"}}},{"text":") under Creative Commons Attribution CC-BY-SA 3.0 ("},{"text":"http://creativecommons.org/licenses/b...","navigationEndpoint":{"urlEndpoint":{"url":"http://creativecommons.org/licenses/by-sa/3.0/legalcode","target":"TARGET_NEW_WINDOW"}}},{"text":")"}]},"moreButton":{"toggleButtonRenderer":{"isToggled":false,"isDisabled":false,"defaultIcon":{"iconType":"EXPAND"},"defaultText":{"runs":[{"text":"More"}]},"toggledIcon":{"iconType":"COLLAPSE"},"toggledText":{"runs":[{"text":"Less"}]}}}}}]}}}}]}},"header":{"musicImmersiveHeaderRenderer":{"title":{"runs":[{"text":"Queen"}]},"subscriptionButton":{"subscribeButtonRenderer":{"subscriberCountText":{"runs":[{"text":"19.1M"}]},"subscribed":false,"enabled":true,"type":"FREE","channelId":"UCiMhD4jzUqG-IgPzUmmytRQ","showPreferences":false,"subscriberCountWithSubscribeText":{"runs":[{"text":"19.1M"}]},"subscribedButtonText":{"runs":[{"text":"Subscribed"}]},"unsubscribedButtonText":{"runs":[{"text":"Subscribe"}]},"unsubscribeButtonText":{"runs":[{"text":"Unsubscribe"}]},"serviceEndpoints":[{"subscribeEndpoint":{"channelIds":["UCiMhD4jzUqG-IgPzUmmytRQ"],"params":"EgIIGxgA"}},{"signalServiceEndpoint":{"signal":"CLIENT_SIGNAL","actions":[{"openPopupAction":{"popup":{"confirmDialogRenderer":{"dialogMessages":[{"runs":[{"text":"Unsubscribe from "},{"text":"Queen"},{"text":"?"}]}],"confirmButton":{"buttonRenderer":{"style":"STYLE_BRAND","size":"SIZE_DEFAULT","text":{"runs":[{"text":"Unsubscribe"}]},"serviceEndpoint":{"unsubscribeEndpoint":{"channelIds":["UCiMhD4jzUqG-IgPzUmmytRQ"]}}}},"cancelButton":{"buttonRenderer":{"style":"STYLE_TEXT","size":"SIZE_DEFAULT","text":{"runs":[{"text":"Cancel"}]}}}}},"popupType":"DIAL