seconds":"82630","endTimeMilliseconds":"92640","metadata":{"id":"11"}}},{"lyricLine":"If I'm not back again this time tomorrow","cueRange":{"startTimeMilliseconds":"92640","endTimeMilliseconds":"97440","metadata":{"id":"12"}}},{"lyricLine":"Carry on, carry on as if nothing really matters","cueRange":{"startTimeMilliseconds":"97440","endTimeMilliseconds":"105460","metadata":{"id":"13"}}},{"lyricLine":"♪","cueRange":{"startTimeMilliseconds":"105460","endTimeMilliseconds":"114820","metadata":{"id":"14"}}},{"lyricLine":"Too late, my time has come","cueRange":{"startTimeMilliseconds":"114820","endTimeMilliseconds":"121170","metadata":{"id":"15"}}},{"lyricLine":"Sends shivers down my spine, body's aching all the time","cueRange":{"startTimeMilliseconds":"121170","endTimeMilliseconds":"128580","metadata":{"id":"16"}}},{"lyricLine":"Goodbye everybody, I've got to go","cueRange":{"startTimeMilliseconds":"128580","endTimeMilliseconds":"134800","metadata":{"id":"17"}}},{"lyricLine":"Gotta leave you all behind, and face the truth","cueRange":{"startTimeMilliseconds":"134800","endTimeMilliseconds":"142040","metadata":{"id":"18"}}},{"lyricLine":"Mama, ooh (any way the wind blows)","cueRange":{"startTimeMilliseconds":"142040","endTimeMilliseconds":"148800","metadata":{"id":"19"}}},{"lyricLine":"I don't wanna die","cueRange":{"startTimeMilliseconds":"148800","endTimeMilliseconds":"152070","metadata":{"id":"20"}}},{"lyricLine":"I sometimes wish I'd never been born at all","cueRange":{"startTimeMilliseconds":"152070","endTimeMilliseconds":"157510","metadata":{"id":"21"}}},{"lyricLine":"♪","cueRange":{"startTimeMilliseconds":"157510","endTimeMilliseconds":"186160","metadata":{"id":"22"}}},{"lyricLine":"I see a little silhouetto of a man","cueRange":{"startTimeMilliseconds":"186160","endTimeMilliseconds":"188870","metadata":{"id":"23"}}},{"lyricLine":"Scaramouche, Scaramouche, will you do the Fandango?","cueRange":{"startTimeMilliseconds":"188870","endTimeMilliseconds":"192470","metada